#include "rinkfit/joint_al.hpp"
#include <ceres/jet.h>
#include <fstream>
#include <iostream>
#include <cstring>
namespace {using namespace rinkfit;using J=eventio::Json;
void need(bool a,const std::string&s){if(!a)throw std::runtime_error(s);}
std::uint64_t bits(double d){std::uint64_t b;std::memcpy(&b,&d,sizeof(b));return b;}
std::string bytes_sha(const std::vector<double>&v){std::vector<std::uint8_t>b(v.size()*sizeof(double));if(!b.empty())std::memcpy(b.data(),v.data(),b.size());return eventio::sha256(b);}
std::array<double,3> rates(const EventModel&e,double time){const double half=std::abs(e.blocks[0].values[31])/2;
#ifdef RINKFIT_RESTRICTED_CUBIC_CERTIFICATE
 return e.restricted_trajectory_derivative_bounds(time-half,time+half);
#else
 auto c=[&](int i,int k){if(k<2&&i==e.dependent_control){double s=0,pivot=0;for(int j=0;j<4;++j){if(e.reference_indices[j]==i)pivot=e.reference_weights[j];else s+=e.reference_weights[j]*e.blocks[e.control_block_begin+e.reference_indices[j]].values[k];}return -s/pivot;}return e.blocks[e.control_block_begin+i].values[k];};std::array<double,3>r{};const int begin=int(std::floor((time-half-e.first_control_time)/e.dt))-2,end=int(std::floor((time+half-e.first_control_time)/e.dt))+2;for(int i=std::max(0,begin);i<=std::min(e.n_controls-2,end);++i)for(int k=0;k<3;++k)r[k]=std::max(r[k],std::abs(c(i+1,k)-c(i,k))/e.dt);for(auto&v:r)v=std::nextafter(v*(1+1e-12)+1e-12,INFINITY);return r;
#endif
}
J sample(JointEventModel&m,EventModel&legacy,const J&r){const auto l=m.layout(m.shot_map.at(r.at("shot_id")),r.at("material"),r.at("path"),r.at("native_pts"),r.value("width_block",-1),r.value("width_sign",0));const double s=r.at("station"),row=r.at("row");const auto p=m.pointers(l);auto q=m.predict_for_al(l,s,row,p.data());auto root=m.certified_projection(legacy,l,s,row);J out={{"original_row",r.at("original_row")},{"shot_id",r.at("shot_id")},{"native_pts",r.at("native_pts")},{"explicit_arithmetic_valid",q.arithmetic_valid},{"explicit_physical_status",int(q.physical_status)},{"explicit_uv_bits",{bits(q.uv[0]),bits(q.uv[1])}},{"depth_ray_Brown_bits",{bits(q.depth),bits(q.ray_radius_sq),bits(q.brown_lower)}},{"root_uv",root.uv},{"root_uv_bits",{bits(root.uv[0]),bits(root.uv[1])}},{"root_row",root.row},{"root_equality_px",root.equality_px},{"root_valid",root.valid},{"root_unique",root.unique},{"root_count",root.roots},{"root_reason",root.reason},{"implicit_denominator_bits",bits(root.implicit_denominator)}};
 for(int seed=0;seed<2;++seed){using T=ceres::Jet<double,1>;std::vector<std::vector<T>>store;std::vector<const T*>ptrs;store.reserve(l.block_ids.size());for(auto bi:l.block_ids){store.emplace_back();for(double v:m.blocks[bi].values)store.back().push_back(T(v));ptrs.push_back(store.back().data());}T js(s),jr(row);if(seed==0)js.v[0]=1;else jr.v[0]=1;auto a=m.predict_for_al(l,js,jr,ptrs.data());out[seed==0?"station_Jet_bits":"row_Jet_bits"]={bits(a.uv[0].a),bits(a.uv[1].a),bits(a.uv[0].v[0]),bits(a.uv[1].v[0]),bits(a.depth.a),bits(a.depth.v[0]),bits(a.ray_radius_sq.a),bits(a.ray_radius_sq.v[0]),bits(a.brown_lower.a),bits(a.brown_lower.v[0])};}
 return out;}
}
int main(int argc,char**argv){try{using namespace rinkfit;need(argc>=2,"missing audit mode");const std::string mode=argv[1];J out;
 if(mode=="--constraints"){need(argc==6,"usage --constraints MODEL PACKET CP OUT_JSON");auto m=JointEventModel::load(argv[2]);auto p=JointPacket::load(argv[3],m);JointALBuilder b(std::move(m),std::move(p));std::ifstream f(argv[4]);auto cp=read_checkpoint(f);b.restore_state(cp.state);need(b.capture_state().token()==cp.state.token(),"complete state roundtrip failed");const auto schema=b.core.packet.source_json.at("schema");b.core.packet.source_json={{"schema",schema}};b.core.packet.groups.clear();const auto v=b.evaluate_constraints(cp.state);need(v.state_token==cp.state.token(),"constraint values refer to different state");out={{"schema","rinkfit.complete_actual_AL_constraints_bitwise_digest.v1"},{"source_sha256",eventio::file_sha256(argv[3])},{"model_sha256",eventio::file_sha256(argv[2])},{"checkpoint_sha256",eventio::file_sha256(argv[4])},{"state_token",cp.state.token()},{"inequality_count",v.g.size()},{"equality_count",v.h.size()},{"g_double_bytes_sha256",bytes_sha(v.g)},{"h_double_bytes_sha256",bytes_sha(v.h)},{"source_Query_E_finite_model_and_all_explicit_aux_from_actual_complete_state",true},{"statistical_W_not_part_of_g_h_and_not_evaluated",true},{"fit_or_parameter_change",false}};for(double x:v.g)need(std::isfinite(x),"nonfinite actual g");for(double x:v.h)need(std::isfinite(x),"nonfinite actual h");eventio::atomic_json(argv[5],out);
 }else if(mode=="--samples"){need(argc==5,"usage --samples MODEL INPUT_JSON OUT_JSON");auto m=JointEventModel::load(argv[2]);const auto input=eventio::read_json(argv[3]);need(input.at("model").at("sha256")==eventio::file_sha256(argv[2]),"reference model SHA mismatch");std::vector<EventModel>legacy;for(std::size_t i=0;i<m.shots.size();++i)legacy.push_back(m.legacy_snapshot(int(i)));out={{"schema","rinkfit.actual_native_RS_derivative_certificate_oracle.v1"},{"model_sha256",eventio::file_sha256(argv[2])},{"reference_sha256",eventio::file_sha256(argv[3])},{"reference_rates",J::array()},{"actual_source_rows",J::array()},{"no_Query_polynomials_in_small_sample_no_Query_factor_claim",true}};for(const auto&t:input.at("reference_rates")){const int si=m.shot_map.at(t.at("shot_id"));const auto bound=rates(legacy.at(si),t.at("local_seconds"));out["reference_rates"].push_back({{"shot_id",t.at("shot_id")},{"native_pts",t.at("native_pts")},{"bounds",bound}});}for(const auto&r:input.at("actual_source_rows"))out["actual_source_rows"].push_back(sample(m,legacy.at(m.shot_map.at(r.at("shot_id"))),r));eventio::atomic_json(argv[4],out);
 }else throw std::runtime_error("unknown audit mode");std::cout<<J({{"passed",true},{"mode",mode},{"fit_or_parameter_change",false}}).dump()<<std::endl;return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
